import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'home-hero-thumb-card';

  const pos = config.scenePosition || { x: -2.5, y: -0.2, z: 0 };
  const rot = config.sceneRotation || { x: 0, y: 0, z: 0 };
  const scl = config.sceneScale || { x: 1, y: 1, z: 1 };
  group.position.set(pos.x, pos.y, pos.z);
  group.rotation.set(rot.x, rot.y, rot.z);
  group.scale.set(scl.x, scl.y, scl.z);

  const baseY = group.position.y;

  // frame + caption strip built from primitives so something exists before mesh loads
  const frameGeo = new THREE.PlaneGeometry(1.6, 1.0);
  const frameMat = new THREE.MeshStandardNodeMaterial({
    color: new THREE.Color('#16161d'),
    roughness: 0.55,
    metalness: 0.45,
  });
  const frame = new THREE.Mesh(frameGeo, frameMat);
  frame.position.z = -0.02;
  group.add(frame);

  const captionGeo = new THREE.PlaneGeometry(1.6, 0.22);
  const captionMat = new THREE.MeshStandardNodeMaterial({
    color: new THREE.Color('#0b0b10'),
    roughness: 0.6,
    metalness: 0.3,
  });
  const caption = new THREE.Mesh(captionGeo, captionMat);
  caption.position.set(0, -0.5 + 0.11, -0.01);
  group.add(caption);

  const edgeGeo = new THREE.PlaneGeometry(1.66, 1.06);
  const edgeMat = new THREE.MeshStandardNodeMaterial({
    color: new THREE.Color('#ff2a38'),
    roughness: 0.5,
    metalness: 0.5,
    emissive: new THREE.Color('#ff2a38'),
    emissiveIntensity: 0.0,
  });
  const edge = new THREE.Mesh(edgeGeo, edgeMat);
  edge.position.z = -0.03;
  edge.visible = false;
  group.add(edge);

  let meshRoot = null;
  let meshDisposables = [];
  try {
    const gltf = ctx.glbLoader.load('/prism-mock/orrery/meshes/gear-a.glb');
    if (gltf && gltf.scene) {
      meshRoot = gltf.scene;
      meshRoot.position.set(0, 0.06, 0.05);
      meshRoot.scale.set(0.9, 0.9, 0.9);
      meshRoot.traverse((child) => {
        if (child.isMesh) {
          meshDisposables.push(child);
          if (child.material) {
            child.material.roughness = Math.min(1, Math.max(0.5, child.material.roughness ?? 0.6));
            child.material.metalness = Math.min(0.55, child.material.metalness ?? 0.4);
            if ('clearcoat' in child.material) {
              child.material.clearcoat = Math.min(0.25, child.material.clearcoat ?? 0.15);
            }
          }
        }
      });
      group.add(meshRoot);
    }
  } catch (e) {
    // mesh load failed silently; frame/caption still render
  }

  let hoverTl = null;
  let pressTl = null;

  const handlers = {
    onPointerOver: () => {
      if (hoverTl) hoverTl.kill();
      edge.visible = true;
      edge.material.emissiveIntensity = 0.6;
      hoverTl = gsap.timeline();
      hoverTl.to(group.position, {
        y: baseY + 0.15,
        duration: 0.7,
        ease: 'power3.out',
      });
    },
    onPointerOut: () => {
      if (hoverTl) hoverTl.kill();
      hoverTl = gsap.timeline();
      hoverTl.to(group.position, {
        y: baseY,
        duration: 0.7,
        ease: 'power3.out',
        onComplete: () => {
          edge.visible = false;
        },
      });
    },
    onPointerDown: () => {
      if (pressTl) pressTl.kill();
      pressTl = gsap.timeline();
      pressTl.to(group.scale, {
        x: scl.x * 0.97,
        y: scl.y * 0.97,
        z: scl.z * 0.97,
        duration: 0.12,
        ease: 'back.out',
      });
    },
    onPointerUp: () => {
      if (pressTl) pressTl.kill();
      pressTl = gsap.timeline();
      pressTl.to(group.scale, {
        x: scl.x,
        y: scl.y,
        z: scl.z,
        duration: 0.12,
        ease: 'back.out',
      });
    },
    onClick: () => {
      if (group.userData.emit) {
        group.userData.emit('hub-home.select', { nodeId: config.id || 'home-hero' });
      }
    },
  };

  group.userData.handlers = handlers;

  group.userData.cleanup = () => {
    if (hoverTl) hoverTl.kill();
    if (pressTl) pressTl.kill();
    frameGeo.dispose();
    frameMat.dispose();
    captionGeo.dispose();
    captionMat.dispose();
    edgeGeo.dispose();
    edgeMat.dispose();
    meshDisposables.forEach((m) => {
      if (m.geometry) m.geometry.dispose();
      if (m.material) {
        if (Array.isArray(m.material)) m.material.forEach((mm) => mm.dispose());
        else m.material.dispose();
      }
    });
  };

  return group;
}
